const e="italie",l=1,s={habitants:"les Italiens",adjectif:"italien",adjectifF:"italienne",devise:"Tout change pour que rien ne change, avec tampon et en trois exemplaires",medaillon:"IT",chaineInfo:"IT NOTIZIE",hymne:"Vive la République et son prochain gouvernement"},n={chambre:"Parlement",chambreLong:"Parlement italien (Chambre des députés et Sénat)",chefGouvernement:"Président du Conseil",chefEtat:"Président de la République (rôle d'arbitre)",passageForce:{label:"Question de confiance",description:"Le gouvernement lie son sort au vote d'un texte : si la confiance est refusée, il tombe. Les députés votent donc souvent oui, en soupirant et en commentant.",news:"Question de confiance sur {loi} : le Parlement vote, les couloirs murmurent"},censure:{label:"Motion de défiance",description:"Une fraction des parlementaires peut déposer une motion de défiance contre le gouvernement. Elle est surtout redoutée quand elle est précédée de la phrase « on ne peut plus continuer ainsi ».",news:"Motion de défiance déposée : la coalition vérifie ses extincteurs"},dissolution:{label:"Dissolution du Parlement",description:"Le Président de la République peut dissoudre les chambres après avoir consulté leurs présidents et son agenda. Une nouvelle coalition est généralement en préparation depuis longtemps.",news:"Parlement dissous : on prépare déjà le prochain gouvernement"}},t={type:"legislatives",label:"Élections législatives",intro:"Six semaines de campagne, des alliances qui changent à chaque marché, des affiches où tout le monde sourit pour la première et la dernière fois. Les sondages, eux, changent de camp par prudence.",adversaires:[{id:"adv-it-1",name:"Aurelio Vestrini",parti:"Démocrates du Peuple",style:"chiffres",punchlines:["Mon adversaire promet des ponts : j'ai le devis, le calendrier et trois contre-devis.","Je ne promets pas de miracles, je promets un cahier des charges.","Un gouvernement qui dure, c'est un gouvernement qui lit ses dossiers."],genre:"m"},{id:"adv-it-2",name:"Donatella Ferrucci",parti:"Frères de la Patrie",style:"emotion",punchlines:["Ce pays a des racines, des clochers et une cuisine : je défendrai les trois.","Je ne suis pas un homme politique, je suis la voix de la place du village.","Mon adversaire parle d'Europe ; moi, je parle de ma grand-mère."],genre:"f"},{id:"adv-it-3",name:"Tullio Bellandi",parti:"Mouvement du Ciel Étoilé",style:"attaque",punchlines:["Ils sont tous pareils, sauf moi, et je viens de changer de camp.","Le système est pourri, mais j'y suis arrivé par l'escalier principal.","Vous voulez un changement ? Je vous le promets avant mon prochain changement."],genre:"m"}],nuitElectorale:"À Rome, la nuit électorale commence par une projection, se poursuit par une autre projection contraire, et se termine à l'aube avec trois coalitions qui se déclarent victorieuses, chacune devant une caméra différente."},i=[{id:"italie-guichet-unique",title:"Guichet unique contre la bureaucratie",domain:"institutions",description:"Remplacer quarante-deux tampons par une seule autorisation numérique. Les timbres fiscaux, déjà en deuil, réclament une cérémonie d'adieu officielle.",accroche:"Un seul guichet pour tout, ouvert le mardi matin entre dix et dix heures dix.",effects:{economie:4,popularite:3,budget:-2},delayed:[{delay:3,effects:{economie:2,popularite:1},label:"Un dossier traité en trois semaines : la préfecture exige un justificatif"}],groupStance:{"fratelli-patria":.6,"democratici-popolo":.4,"mouvement-ciel":.5,"lega-nord-sud":.7,"forza-centro":.8,"verts-gauche-it":.2,"azione-riforma":.9},streetAnger:0},{id:"italie-procedures-accelerees",title:"Accélération des procédures judiciaires",domain:"justice",description:"Fixer un délai maximum aux procès pour qu'ils se terminent avant que les accusés n'aient l'âge de la retraite. Les avocats saluent l'initiative et plaident pour un report.",accroche:"Les procès iront plus vite, mais l'avocat gardera le temps de finir son café.",effects:{economie:3,cohesion:2,popularite:-2,assemblee:-2},delayed:[{delay:4,effects:{economie:2,cohesion:1},label:"Le premier procès tient en moins de dix ans"}],groupStance:{"fratelli-patria":.3,"democratici-popolo":.5,"mouvement-ciel":.2,"lega-nord-sud":.2,"forza-centro":.6,"verts-gauche-it":.4,"azione-riforma":.9},streetAnger:.2},{id:"italie-entretien-ponts-viaducs",title:"Plan d'entretien des ponts et viaducs",domain:"ecologie",description:"Auditer, réparer et surveiller les infrastructures avant qu'elles n'attirent l'attention du journal de vingt heures. Un viaduc est considéré comme « en bonne santé » quand il ne bouge qu'un peu.",accroche:"Les ponts seront vérifiés, ils en profiteront pour se tenir bien droits.",effects:{budget:-6,securite:4,economie:2,popularite:2},delayed:[{delay:4,effects:{securite:2,economie:1},label:"Le viaduc passe l'inspection, de justesse"}],groupStance:{"fratelli-patria":.4,"democratici-popolo":.6,"mouvement-ciel":.5,"lega-nord-sud":.4,"forza-centro":.5,"verts-gauche-it":.6,"azione-riforma":.7},streetAnger:0},{id:"italie-prime-de-majorite",title:"Prime de majorité pour la stabilité",domain:"institutions",description:"Offrir un bonus de sièges à la coalition arrivée en tête afin de dépasser la durée moyenne d'un gouvernement. L'opposition parle de « piège institutionnel », les experts de « gain de six mois, au moins ».",accroche:"Qui gagne gouverne, du moins jusqu'à la prochaine réunion de coalition.",effects:{assemblee:-4,popularite:3,cohesion:-2},delayed:[{delay:4,effects:{assemblee:3},label:"Un gouvernement qui dépasse dix-huit mois, une première pour la décennie"}],groupStance:{"fratelli-patria":.8,"democratici-popolo":-.3,"mouvement-ciel":-.7,"lega-nord-sud":.5,"forza-centro":.6,"verts-gauche-it":-.8,"azione-riforma":.5},streetAnger:.2},{id:"italie-autonomie-differenciee",title:"Autonomie différenciée des régions",domain:"institutions",description:"Permettre aux régions les plus riches de négocier de nouvelles compétences. Les autres régions demandent d'urgence à négocier aussi, mais en plus grand.",accroche:"Chaque région a désormais son mot à dire, voire la phrase et les points de suspension.",effects:{economie:2,assemblee:2,cohesion:-3,popularite:-1},delayed:[{delay:4,effects:{cohesion:-1,economie:1},label:"Chaque région exige son propre tampon"}],groupStance:{"fratelli-patria":0,"democratici-popolo":-.7,"mouvement-ciel":-.5,"lega-nord-sud":1,"forza-centro":.3,"verts-gauche-it":-.8,"azione-riforma":.2},streetAnger:.2},{id:"italie-plan-mezzogiorno",title:"Plan d'investissement pour le Mezzogiorno",domain:"travail",description:"Relier le Sud par des routes, des trains rapides et une connexion internet qui supporte le streaming. Les promesses de ce type sont presque centenaires et presque toujours enthousiastes.",accroche:"Le Sud reçoit un plan, et en retour offre ses oranges à la commission d'évaluation.",effects:{budget:-5,cohesion:4,economie:3,popularite:2},delayed:[{delay:4,effects:{economie:2,cohesion:2},label:"Un chantier avance, deux autres sont inaugurés"}],groupStance:{"fratelli-patria":.3,"democratici-popolo":.7,"mouvement-ciel":.8,"lega-nord-sud":-.3,"forza-centro":.2,"verts-gauche-it":.8,"azione-riforma":.4},streetAnger:0},{id:"italie-depart-quota",title:"Départ anticipé à la retraite par quotas",domain:"retraites",description:"Autoriser le départ avant l'âge légal si la somme de l'âge et des années de cotisation atteint un chiffre magique. Les experts comptables sont priés de ne pas faire de commentaires.",accroche:"Partir en retraite par quotas : on compte les années, et surtout les cousins.",effects:{popularite:4,budget:-5,assemblee:1},delayed:[{delay:4,effects:{budget:-2},label:"L'addition de la retraite anticipée arrive, avec intérêts"}],groupStance:{"fratelli-patria":.4,"democratici-popolo":.6,"mouvement-ciel":.5,"lega-nord-sud":.8,"forza-centro":0,"verts-gauche-it":.7,"azione-riforma":-.8},streetAnger:0},{id:"italie-recu-obligatoire",title:"Reçu fiscal obligatoire au comptoir",domain:"justice",description:"Rendre le reçu obligatoire pour chaque café, chaque pizza, chaque fleur. L'espresso garde le prix mais perd sa discrétion, ce qui inquiète le comptoir.",accroche:"Le reçu devient obligatoire, le café au comptoir reste, lui, une affaire de confiance.",effects:{budget:4,popularite:-4,economie:-1},delayed:[{delay:3,effects:{budget:2},label:"Les recettes progressent, les cafés aussi les pourboires"}],groupStance:{"fratelli-patria":0,"democratici-popolo":.5,"mouvement-ciel":.3,"lega-nord-sud":-.5,"forza-centro":-.4,"verts-gauche-it":.6,"azione-riforma":.8},streetAnger:.4},{id:"italie-droit-entree-villes-art",title:"Droit d'entrée dans les villes d'art",domain:"ecologie",description:"Faire payer un billet aux visiteurs des centres historiques les plus saturés. Les gondoles et les cartes postales protestent d'une même voix.",accroche:"Pour entrer dans la ville d'art, une taxe, et un guide qui parle un peu trop.",effects:{ecologie:3,budget:2,popularite:-2,economie:-1},delayed:[{delay:3,effects:{ecologie:2,cohesion:1},label:"Les ruelles respirent, les terrasses aussi"}],groupStance:{"fratelli-patria":-.2,"democratici-popolo":.4,"mouvement-ciel":.3,"lega-nord-sud":-.3,"forza-centro":-.3,"verts-gauche-it":.9,"azione-riforma":.5},streetAnger:.2},{id:"italie-protection-appellations",title:"Protection renforcée des appellations d'origine",domain:"agriculture",description:"Défendre en Europe la pâte, le jambon et le fromage contre les imitations. Le ministre de l'Agriculture porte un costume tricolore pour la signature, avec un parmesan en guise de stylo.",accroche:"Le fromage a désormais un passeport, et le jambon un avocat de famille.",effects:{economie:2,international:2,popularite:1,budget:-1},delayed:[{delay:3,effects:{economie:2},label:"Les exportations d'authenticité progressent"}],groupStance:{"fratelli-patria":.8,"democratici-popolo":.3,"mouvement-ciel":.4,"lega-nord-sud":.8,"forza-centro":.5,"verts-gauche-it":.2,"azione-riforma":.2},streetAnger:0}],a=[{id:"italie-tampon-manquant",title:"Le tampon manquant",category:"economie",description:"Une usine attend un permis depuis quatre ans, faute d'un tampon qui doit exister dans un tiroir de Rome, de Milan ou de Naples. Le directeur envisage de s'installer ailleurs, ou d'ouvrir un restaurant.",weight:6,choices:[{id:"commissaire",label:"Nommer un commissaire extraordinaire",description:"Un fonctionnaire spécial, avec un seul tampon, pour tout débloquer.",effects:{economie:3,budget:-2,assemblee:-1,popularite:2},delayed:[{delay:3,effects:{economie:2},label:"L'usine ouvre avant la fin de l'année"}],news:"Un commissaire extraordinaire est nommé : il possède le tampon"},{id:"simplifier",label:"Lancer une simplification administrative",description:"Un décret pour supprimer trois décrets.",effects:{economie:2,popularite:-1,assemblee:-1},delayed:[{delay:4,effects:{economie:2,popularite:1},label:"Quelques formulaires disparaissent, d'autres naissent"}],news:"Simplification annoncée : le décret fait onze pages"},{id:"patience",label:"Conseiller de patienter",description:"Au fond, tout finit par arriver.",effects:{popularite:-3,economie:-3},news:"Le gouvernement conseille la patience : un tampon arrivera peut-être"}]},{id:"italie-viaduc-fissure",title:"Le viaduc fissuré",category:"securite",description:"Une inspection révèle qu'un viaduc autoroutier a vieilli plus vite que son budget d'entretien. Les ingénieurs recommandent de ne pas s'y arrêter pour la photo.",weight:5,minTurn:2,conditions:[{gauge:"securite",op:"<",value:58}],choices:[{id:"fermer-reparer",label:"Fermer et réparer en urgence",description:"Reroutage, chantier et patience nationale.",effects:{budget:-5,securite:4,economie:-1,popularite:-1},delayed:[{delay:3,effects:{securite:2,popularite:1},label:"Le viaduc rouvre et tient debout"}],news:"Viaduc fermé pour travaux : les déviations sont, elles aussi, fermées"},{id:"audit-national",label:"Lancer un audit de toutes les infrastructures",description:"Compter les ponts un par un, puis les compter à nouveau.",effects:{budget:-3,securite:2,popularite:1},news:"Audit national lancé : 14 000 ponts attendent leur verdict"},{id:"minimiser",label:"Minimiser et rouvrir à la circulation légère",description:"Un panneau, un rideau et une prière.",effects:{popularite:-3,securite:-4,budget:1},news:"Viaduc rouvert à titre « limité » : un panneau demande de rouler avec prudence"}]},{id:"italie-coalition-vacille",title:"La coalition vacille",category:"politique",description:"Un parti de la majorité menace de quitter le gouvernement sur une question de ponts, de tampons ou de chaises. Les journalistes écrivent l'article « la fin du gouvernement » en préparant l'article « il tient encore ».",weight:6,minTurn:2,conditions:[{gauge:"assemblee",op:"<",value:50}],choices:[{id:"rimpasto",label:"Faire un remaniement pour calmer les ambitions",description:"Quelques ministères en échange de quelques fidélités.",effects:{assemblee:4,popularite:-2,budget:-1},news:"Remaniement : les fauteuils changent de propriétaire, la ligne reste"},{id:"question-confiance",label:"Poser la question de confiance",description:"Menacer de tout arrêter si l'on ne vote pas.",effects:{assemblee:3,popularite:-3,international:-1},news:"Question de confiance : le gouvernement mise sa survie sur un jeudi"},{id:"laisser-tomber",label:"Laisser le partenaire partir",description:"Compter sur des renforts discrets venus d'ailleurs.",effects:{assemblee:-4,popularite:-1,international:-1},news:"Un parti quitte la majorité, un autre frappe à la porte"}]},{id:"italie-greve-du-vendredi",title:"La grève du vendredi",category:"social",description:"Les syndicats de transport appellent à la grève un vendredi, comme tous les vendredis. Des millions d'actifs découvrent la joie du week-end allongé et la douceur du covoiturage.",weight:5,minTurn:2,choices:[{id:"table-ronde",label:"Réunir une table ronde",description:"Un café, une négociation, trois communiqués.",effects:{cohesion:2,budget:-3,popularite:1},delayed:[{delay:3,effects:{cohesion:1},label:"La grève du vendredi suivant est un peu moins longue"}],news:"Table ronde sur les transports : on se sépare avec des promesses et un pourboire"},{id:"precettation",label:"Réquisitionner les personnels",description:"Ordonner un service minimum par décret.",effects:{economie:1,popularite:-3,cohesion:-3},news:"Réquisition des personnels : le droit de grève, c'est aussi un droit d'être réquisitionné"},{id:"laisser-faire",label:"Laisser passer et miser sur la lassitude",description:"Les week-ends allongés, on y prend goût.",effects:{economie:-2,popularite:-2},news:"Grève du vendredi : le gouvernement attend dimanche"}]},{id:"italie-seisme-apennin",title:"Séisme dans l'Apennin",category:"climat",description:"Une secousse de magnitude 5,8 frappe un bourg de montagne, endommageant l'église, la mairie et la boulangerie. Les habitants rappellent que les normes antisismiques existaient déjà, dans une circulaire.",weight:3,minTurn:3,choices:[{id:"reconstruction",label:"Lancer une reconstruction exemplaire",description:"Des maisons solides, un calendrier réaliste et un chef de chantier.",effects:{budget:-5,securite:3,cohesion:3,popularite:2},delayed:[{delay:4,effects:{cohesion:2,popularite:1},label:"Les premières maisons sont reconstruites, la boulangerie en premier"}],news:"Reconstruction promise : les habitants demandent à voir les grues"},{id:"aide-immediate",label:"Verser une aide d'urgence immédiate",description:"Des chèques, des tentes et des repas chauds.",effects:{budget:-3,popularite:3,cohesion:2},news:"Aide d'urgence versée : les sinistrés remercient et réclament la suite"},{id:"commission",label:"Créer une commission d'enquête",description:"Chercher les causes, les responsables et si possible les décrets.",effects:{budget:-1,popularite:-3,cohesion:-1},news:"Commission d'enquête créée : elle se réunira après les travaux"}]},{id:"italie-spread-dette",title:"Le spread s'affole",category:"economie",description:"L'écart entre les taux d'emprunt italiens et allemands atteint un niveau que les économistes qualifient d'« éloquent ». Le ministre de l'Économie assure que « les fondamentaux sont solides », sans préciser desquels.",weight:5,minTurn:3,conditions:[{gauge:"budget",op:"<",value:42}],choices:[{id:"austerite",label:"Annoncer un plan de rigueur",description:"Couper dans les dépenses et rassurer Bruxelles.",effects:{budget:5,popularite:-5,economie:-2,international:2},news:"Plan de rigueur annoncé : les marchés approuvent, les électeurs prennent note"},{id:"bruxelles",label:"Demander un accord à Bruxelles",description:"Négocier un calendrier de redressement.",effects:{international:-2,budget:2,economie:1,popularite:-1},delayed:[{delay:3,effects:{budget:2,international:1},label:"Le spread se détend, un peu"}],news:"Négociation avec Bruxelles : un café diplomatique et un calendrier"},{id:"ignorer-spread",label:"Dire que tout va bien",description:"Un communiqué optimiste, une photo sur la terrasse.",effects:{popularite:1,budget:-3,economie:-3},news:"Le gouvernement affirme que tout va bien : les taux n'ont pas été consultés"}]},{id:"italie-querelle-appellations",title:"Querelle sur les appellations",category:"agriculture",description:"Un fabricant étranger vend un « parmesan » qui n'a jamais vu de parmesan. Les fromagers italiens, déterminés, brandissent des meules et des certificats.",weight:3,choices:[{id:"plainte-europe",label:"Porter plainte devant les instances européennes",description:"Un dossier de trois cents pages, relié en cuir.",effects:{international:-1,economie:2,popularite:2},delayed:[{delay:3,effects:{economie:2,international:1},label:"La Commission tranche en faveur de la meule"}],news:"Plainte déposée : le parmesan trouve son avocat"},{id:"campagne-promotion",label:"Lancer une campagne d'authenticité",description:"Un spot télévisé avec une grand-mère et un fromage.",effects:{popularite:2,budget:-2,economie:1},news:"Campagne d'authenticité : la grand-mère signe l'affiche"},{id:"negocier-marque",label:"Négocier un étiquetage commun",description:"Chacun garde son nom, nul ne garde sa dignité.",effects:{international:2,economie:-1,popularite:-2},news:"Étiquetage négocié : l'imitation reçoit un petit astérisque"}]},{id:"italie-victoire-finale",title:"Victoire en finale",category:"politique",kind:"evenement",description:"L'équipe nationale gagne une finale européenne aux tirs au but. Les rues se couvrent de drapeaux, les klaxons préparent leur grand solo et le ministre des Sports reçoit trois appels de remerciement non sollicités.",weight:3,conditions:[{gauge:"popularite",op:">",value:38}],choices:[{id:"recevoir-equipe",label:"Recevoir l'équipe au palais",description:"Une photo officielle et quelques serviettes fraîches.",effects:{popularite:3,cohesion:3,budget:-1},news:"L'équipe reçue au Palais Chigiano : le trophée occupe la moitié du salon"},{id:"jour-ferie",label:"Décréter un jour férié exceptionnel",description:"Un lundi de gloire.",effects:{popularite:4,economie:-2,cohesion:2},news:"Jour férié décrété : l'économie marque un but contre son camp"},{id:"discret",label:"Se féliciter par un communiqué sobre",description:"Un tweet, un drapeau, une sobre fierté.",effects:{popularite:2,cohesion:1},news:"Le gouvernement félicite l'équipe par un communiqué d'une ligne et demie"}]}],r=[{id:"italie-tampons-supprimes",title:"Simplifier la vie administrative",brief:"Gagnez 4 points d'économie : un tampon supprimé, c'est un point gagné, au moins en théorie.",objective:{type:"gaugeGain",gauge:"economie",value:4},reward:{economie:2,popularite:1},news:"Administration : un tampon sur dix disparaît, officiellement"},{id:"italie-gouvernement-tient",title:"Durer plus de dix-huit mois",brief:"Gardez un indice d'assemblée à 55 : l'objectif est de battre le record du gouvernement le plus long de la décennie.",objective:{type:"gaugeAtLeast",gauge:"assemblee",value:55},reward:{assemblee:2,popularite:1},news:"Coalition : elle tient, au grand étonnement de ses membres"},{id:"italie-spread-rassure",title:"Rassurer les marchés et Bruxelles",brief:"Un budget à 48 : ce n'est pas la perfection, c'est la pause café de la rigueur.",objective:{type:"gaugeAtLeast",gauge:"budget",value:48},reward:{budget:2,international:1},news:"Budget : le spread se détend, légèrement"},{id:"italie-sans-voyant-rouge",title:"Un trimestre sans voyant rouge",brief:"Aucune jauge dans le rouge : un exploit, selon la tradition nationale.",objective:{type:"noRedGauge"},reward:{popularite:1,cohesion:1},news:"Aucune jauge dans le rouge : la presse n'y croit pas, puis y croit"}],o=JSON.parse('{"medias":["Le Courrier du Campanile","Radio Espresso","La Gazette du Spritz","Tribuna 24","Le Quotidien du Tampon"],"journalistes":[{"id":"italie-j-giulia-santorelli","name":"Giulia Santorelli","media":"Le Courrier du Campanile","style":"incisive : relance en citant votre dernier remaniement, et le précédent","genre":"f"},{"id":"italie-j-matteo-brancaleoni","name":"Matteo Brancaleoni","media":"Radio Espresso","style":"volubile : pose une question de quatre minutes qui se termine par « n’est-ce pas ? »","genre":"m"},{"id":"italie-j-chiara-vellutini","name":"Chiara Vellutini","media":"La Gazette du Spritz","style":"malicieuse : sourit toujours avant la question qui fâche","genre":"f"},{"id":"italie-j-ottavio-mancuso","name":"Ottavio Mancuso","media":"Tribuna 24","style":"tenace : ne lâche jamais un chiffre, surtout le mauvais","genre":"m"},{"id":"italie-j-livia-dalmonte","name":"Livia Dalmonte","media":"Le Quotidien du Tampon","style":"méthodique : demande le formulaire correspondant à chaque réponse","genre":"f"},{"id":"italie-j-bruno-cascella","name":"Bruno Cascella","media":"Radio Espresso","style":"nostalgique : compare tout à un gouvernement de trois semaines","genre":"m"},{"id":"italie-j-serena-marinucci","name":"Serena Marinucci","media":"La Gazette du Spritz","style":"gourmande : prépare ses relances en attendant l’arrivée du café","genre":"f"}],"questions":[{"id":"italie-q-sondage-bas","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":40},"text":"Chef du gouvernement, votre cote de confiance descend plus vite qu’un ascenseur de palais Renaissance. À quelle heure la coalition vous a-t-elle prévenu qu’elle réfléchissait à l’après ?","answers":[{"tone":"franche","label":"Les chiffres sont mauvais et je ne les contesterai pas. Je dois mieux expliquer ce que nous faisons, et le faire avant l’été.","effects":{"popularite":5,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les alliés cherchent déjà la sortie"}],"news":"Le Président du Conseil reconnaît la chute des sondages"},{"tone":"langue-de-bois","label":"Un sondage est un instantané, et ce gouvernement est une longue exposition. Nous gardons le cap, et le cap garde le silence.","effects":{"popularite":2,"assemblee":-2},"news":"« Un instantané » : le Président du Conseil relativise"},{"tone":"offensive","label":"Ceux qui commentent les sondages ne gouvernent pas, et ceux qui gouvernent ne commentent pas. Je vous laisse choisir votre camp.","effects":{"popularite":4,"international":-2,"cohesion":-3},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"La polémique du dimanche s’éternise"}],"news":"Le Président du Conseil renvoie les sondeurs à leurs tableaux"}]},{"id":"italie-q-sondage-haut","theme":"popularite","condition":{"gauge":"popularite","op":">","value":62},"text":"Vos sondages sont si bons que l’opposition parle de les faire vérifier par un notaire. Que répondez-vous à ceux qui y voient le signe avant-coureur de la chute ?","answers":[{"tone":"franche","label":"Je sais que ce crédit se retire aussi vite qu’il s’accorde. Je compte l’utiliser pour des réformes, pas pour des photos.","effects":{"popularite":3,"assemblee":2,"economie":-2},"news":"Le Président du Conseil promet de ne pas dormir sur ses lauriers"},{"tone":"langue-de-bois","label":"La popularité est un vent, et un chef de gouvernement doit apprendre à naviguer sans se plaindre de la météo.","effects":{"popularite":2,"assemblee":-3},"news":"Le Président du Conseil file la métaphore marine"},{"tone":"offensive","label":"Ceux qui prédisent ma chute prédisent aussi la pluie tous les jours : ils finiront par avoir raison une fois.","effects":{"popularite":4,"cohesion":-3,"international":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les alliés notent la désinvolture"}],"news":"Le Président du Conseil se moque des oiseaux de mauvais augure"}]},{"id":"italie-q-economie-basse","theme":"economie","condition":{"gauge":"economie","op":"<","value":42},"text":"La production recule, les PME exportatrices serrent les dents et la dette ne dort jamais. Quel miracle économique comptez-vous annoncer cette semaine, ou faut-il attendre la fête patronale ?","answers":[{"tone":"franche","label":"Il n’y a pas de miracle, seulement des efforts. Nous allégerons les charges des PME, mais il faudra aussi réduire d’autres dépenses.","effects":{"economie":5,"pouvoirAchat":-3},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les commandes repartent doucement"}],"news":"Le gouvernement promet de l’air aux PME, mais pas de miracle"},{"tone":"langue-de-bois","label":"Nous suivons la situation avec la plus grande attention, et nous continuerons à la suivre jusqu’à ce qu’elle nous suive.","effects":{"economie":2,"popularite":-2},"news":"L’économie « suivie avec la plus grande attention »"},{"tone":"offensive","label":"Notre industrie de précision est la meilleure du continent. Ceux qui disent le contraire n’ont jamais ouvert une montre.","effects":{"economie":4,"international":-3,"budget":-3},"delayed":[{"delay":2,"effects":{"budget":-2},"label":"Le coût du plan se précise"}],"news":"Le Président du Conseil vante l’industrie de précision"}]},{"id":"italie-q-economie-haute","theme":"economie","condition":{"gauge":"economie","op":">","value":64},"text":"La croissance est au rendez-vous, au point que le trésorier d’un petit club de bocce demande une audience. Les Italiens verront-ils la couleur de cette prospérité, ou seulement le graphique ?","answers":[{"tone":"franche","label":"La prospérité doit se voir dans les salaires, pas seulement dans les graphiques. Une partie ira donc aux revenus des ménages.","effects":{"pouvoirAchat":5,"budget":-3},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les ménages sentent la différence"}],"news":"Le gouvernement veut partager le fruit de la croissance"},{"tone":"langue-de-bois","label":"La croissance est le résultat du travail de tous, et nous en félicitons tout le monde, y compris ceux qui n’y ont pas cru.","effects":{"economie":2,"popularite":-2},"news":"Le Président du Conseil félicite tout le monde, y compris ses critiques"},{"tone":"offensive","label":"Ce succès est le nôtre : il vient de notre politique, et pas du hasard. Les sceptiques peuvent applaudir en silence.","effects":{"popularite":5,"cohesion":-3,"assemblee":-2},"news":"« Ce succès est le nôtre » : l’exécutif revendique la croissance"}]},{"id":"italie-q-dette","theme":"budget","condition":{"gauge":"budget","op":"<","value":32},"text":"La dette italienne s’annonce comme la plus longue série de l’histoire, avec plus d’épisodes que les feuilletons du dimanche. Qui va payer l’addition, et dans combien de générations ?","answers":[{"tone":"franche","label":"Nous avons trop dépensé et il faut maintenant corriger. Je préfère le dire clairement plutôt que le laisser découvrir en petits caractères.","effects":{"budget":5,"popularite":-4},"delayed":[{"delay":3,"effects":{"international":2},"label":"Les marchés saluent le sérieux budgétaire"}],"news":"Le Président du Conseil avoue : « Nous avons trop dépensé »"},{"tone":"langue-de-bois","label":"La dette est un héritage collectif, géré avec le plus grand soin par les gouvernements successifs. Le suivant la gérera aussi.","effects":{"budget":2,"popularite":-2},"news":"La dette, « héritage collectif » selon l’exécutif"},{"tone":"offensive","label":"Les donneurs de leçons européens n’ont jamais payé notre café. Nous réglerons la dette à notre rythme, et à notre façon.","effects":{"popularite":5,"international":-4,"economie":-3},"delayed":[{"delay":2,"effects":{"international":-3},"label":"Les agences de notation froncent les sourcils"}],"news":"Le gouvernement répond sèchement aux donneurs de leçons européens"}]},{"id":"italie-q-budget-excedent","theme":"budget","condition":{"gauge":"budget","op":">","value":58},"text":"Les caisses de l’État sont pleines pour la première fois depuis l’invention de la lire. Les ministères font déjà la queue devant votre bureau avec des projets : lesquels sauvez-vous, et lesquels vont dormir au tiroir ?","answers":[{"tone":"franche","label":"Nous financerons d’abord ce qui dure : les écoles, les hôpitaux, les routes. Les inaugurations en grande pompe attendront.","effects":{"cohesion":4,"budget":-4,"popularite":-2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les chantiers redémarrent"}],"news":"Le gouvernement investit dans les écoles et les hôpitaux"},{"tone":"langue-de-bois","label":"Chaque euro sera étudié avec soin, comparé, classé, tamponné, puis réexaminé. C’est notre manière de dépenser sagement.","effects":{"budget":2,"economie":-2},"news":"Les excédents seront « tamponnés, puis réexaminés »"},{"tone":"offensive","label":"Baisse d’impôts pour tout le monde ! Cette cagnotte est celle des Italiens, et je ne la garderai pas pour les ministères.","effects":{"popularite":5,"pouvoirAchat":3,"budget":-5,"assemblee":-2},"delayed":[{"delay":3,"effects":{"budget":-2},"label":"Les économistes comptent le manque à gagner"}],"news":"Excédent : le Président du Conseil annonce une baisse d’impôts"}]},{"id":"italie-q-pouvoir-achat","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":38},"text":"Le prix du café au comptoir a franchi un seuil que l’on croyait réservé aux musées. Les Italiens se demandent si l’espresso est encore un droit ou déjà un luxe. Que leur répondez-vous ?","answers":[{"tone":"franche","label":"L’espresso fait partie de la vie quotidienne, et je veux que les ménages puissent le payer. Nous ciblerons les aides sur les plus modestes.","effects":{"pouvoirAchat":5,"budget":-4},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les comptoirs respirent un peu"}],"news":"Le gouvernement veut sauver le café des ménages modestes"},{"tone":"langue-de-bois","label":"Les prix résultent de multiples facteurs internationaux. Nous les suivons, nous les analysons et nous les déplorons.","effects":{"pouvoirAchat":2,"popularite":-2},"news":"Le gouvernement « déplore » le prix du café"},{"tone":"offensive","label":"Si les cafetiers veulent augmenter leurs prix, ils expliqueront le secret de leur machine aux contrôleurs. Je serai présent.","effects":{"popularite":4,"pouvoirAchat":3,"economie":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les cafetiers menacent de fermer le lundi"}],"news":"Le Président du Conseil menace les prix excessifs de l’espresso"}]},{"id":"italie-q-pouvoir-achat-haut","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":">","value":62},"text":"Les paniers de courses se remplissent et les trattorias font le plein. Le risque, dit un économiste, est que l’on consomme trop de pâtes. Voulez-vous freiner la dolce vita ?","answers":[{"tone":"franche","label":"Ce pouvoir d’achat est fragile et je veux le protéger. Nous garderons une réserve pour les mauvais jours.","effects":{"budget":4,"popularite":-3},"news":"Le gouvernement met de côté pour les mauvais jours"},{"tone":"langue-de-bois","label":"Chaque Italien est libre de manger comme il l’entend, et le gouvernement n’a aucune opinion sur la sauce.","effects":{"popularite":2,"economie":-2},"news":"Le gouvernement « n’a aucune opinion sur la sauce »"},{"tone":"offensive","label":"Laissez la dolce vita tranquille ! Elle fait travailler les restaurateurs, les agriculteurs et les grand-mères. Je la protège.","effects":{"popularite":5,"pouvoirAchat":2,"budget":-3},"delayed":[{"delay":3,"effects":{"economie":-2},"label":"L’inflation montre le bout du nez"}],"news":"Le Président du Conseil protège la dolce vita"}]},{"id":"italie-q-securite-basse","theme":"securite","condition":{"gauge":"securite","op":"<","value":40},"text":"Les maires du nord et du sud demandent plus de présence dans les rues, et les préfets plus de budget pour leurs voitures. La sécurité devient-elle un luxe réservé aux provinces calmes ?","answers":[{"tone":"franche","label":"Nous recruterons, nous équiperons et nous répartirons les moyens selon les besoins réels, pas selon les amitiés politiques.","effects":{"securite":5,"budget":-4},"delayed":[{"delay":3,"effects":{"securite":2},"label":"Les patrouilles reviennent dans les quartiers"}],"news":"Sécurité : le gouvernement promet des recrues et des moyens"},{"tone":"langue-de-bois","label":"La sécurité est une priorité de chaque instant, et chaque instant est une priorité. Nous avons donc beaucoup de priorités.","effects":{"securite":2,"popularite":-2},"news":"La sécurité, « priorité de chaque instant »"},{"tone":"offensive","label":"La Ligue des Provinces a raison sur un point : il faut de la fermeté. Les agitateurs rencontreront mes policiers, pas mes sourires.","effects":{"securite":5,"popularite":3,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Les associations dénoncent un ton trop dur"}],"news":"Le Président du Conseil promet la fermeté aux agitateurs"}]},{"id":"italie-q-cohesion-basse","theme":"cohesion","condition":{"gauge":"cohesion","op":"<","value":38},"text":"Le nord et le sud se renvoient les accusations comme deux équipes de calcio un jour de derby. La cohésion nationale tiendra-t-elle jusqu’à la prochaine finale, ou faut-il lancer un plan d’urgence ?","answers":[{"tone":"franche","label":"Le pays ne tient pas par des slogans mais par des écoles, des trains et des hôpitaux. Je concentrerai l’effort là où l’écart est le plus grand.","effects":{"cohesion":5,"budget":-4,"economie":-2},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les investissements arrivent dans le Sud"}],"news":"Un plan pour réduire l’écart entre le nord et le sud"},{"tone":"langue-de-bois","label":"L’unité de la nation est notre bien le plus précieux, et nous la préservons avec constance, humilité, et une grande éloquence.","effects":{"cohesion":2,"popularite":-2},"news":"Le Président du Conseil plaide pour l’unité nationale"},{"tone":"offensive","label":"Le pays se plaint de lui-même depuis les Romains. Je ne vais pas céder au pessimisme des orateurs de comptoir.","effects":{"popularite":4,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"Le Sud se sent traité à la légère"}],"news":"Le Président du Conseil refuse le « pessimisme de comptoir »"}]},{"id":"italie-q-ecologie-basse","theme":"ecologie","condition":{"gauge":"ecologie","op":"<","value":38},"text":"Les fleuves baissent, les glaciers fondent et les vignerons de l’été avancent leurs vendanges. Le pays le plus beau du monde peut-il rester beau sans effort écologique ?","answers":[{"tone":"franche","label":"Nous protégerons les rivières, les côtes et les montagnes, même si cela coûte aux promoteurs. La beauté est notre premier capital.","effects":{"ecologie":5,"economie":-3,"assemblee":-2},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"Les touristes saluent des plages enfin propres"}],"news":"L’exécutif promet de protéger rivières, côtes et montagnes"},{"tone":"langue-de-bois","label":"L’environnement est au cœur de nos préoccupations, et nous allons lui accorder le temps de réflexion qu’il mérite.","effects":{"ecologie":2,"popularite":-2},"news":"L’environnement aura « le temps de réflexion qu’il mérite »"},{"tone":"offensive","label":"Les glaciers fondent depuis longtemps, et l’on ne va pas les arrêter par décret. Je préfère protéger les emplois du tourisme et de l’industrie.","effects":{"economie":4,"popularite":2,"ecologie":-5},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"Les écologistes bloquent un col alpin"}],"news":"Le gouvernement privilégie l’emploi sur les glaciers"}]},{"id":"italie-q-international-bas","theme":"international","condition":{"gauge":"international","op":"<","value":42},"text":"Lors du dernier sommet européen, on dit que votre chaise est restée vide pendant que votre téléphone sonnait dans le couloir. L’Italie est-elle en train de devenir un pays que l’on invite par politesse ?","answers":[{"tone":"franche","label":"Nous avons perdu de l’influence faute de présence. Je serai à chaque table, avec des propositions, pas seulement des photographes.","effects":{"international":5,"popularite":-2,"budget":-2},"delayed":[{"delay":3,"effects":{"international":2},"label":"Rome retrouve la parole au sommet"}],"news":"Le Président du Conseil veut reprendre sa place en Europe"},{"tone":"langue-de-bois","label":"Notre pays est un partenaire fiable, apprécié et écouté. Le fait que personne ne le dise ne change rien à la qualité de l’écoute.","effects":{"international":2,"popularite":-2},"news":"L’Italie « partenaire écouté », assure l’exécutif"},{"tone":"offensive","label":"Qui veut parler à l’Italie sait où est notre ambassade. Nous n’avons pas besoin de courir derrière les sommets des autres.","effects":{"popularite":4,"international":-5,"assemblee":2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les exportateurs s’inquiètent de l’isolement"}],"news":"Le Président du Conseil snobe les sommets lointains"}]},{"id":"italie-q-assemblee-basse","theme":"assemblee","condition":{"gauge":"assemblee","op":"<","value":38},"text":"Au Parlement, la majorité ressemble à un orchestre où chaque musicien joue sa partition en demandant que les autres l’accompagnent. Combien de temps durera le concert ?","answers":[{"tone":"franche","label":"La coalition est faite de partis qui ne pensent pas pareil. Ma tâche est de tenir ensemble les accords, pas d’exiger l’unanimité.","effects":{"assemblee":5,"popularite":-2,"economie":-2},"delayed":[{"delay":3,"effects":{"assemblee":2},"label":"La majorité adopte un calendrier commun"}],"news":"Le Président du Conseil assume les accords de coalition"},{"tone":"langue-de-bois","label":"La majorité est unie sur l’essentiel, divisée sur le reste, et le reste est vaste. Nous avançons dans une harmonie que l’on dit contrastée.","effects":{"assemblee":2,"popularite":-2},"news":"La majorité avance dans une « harmonie contrastée »"},{"tone":"offensive","label":"Qu’on dépose une motion de défiance si l’on veut ! Mais l’on devra expliquer aux électeurs pourquoi l’on préfère un nouveau gouvernement à l’ancien.","effects":{"popularite":3,"assemblee":-5,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-3},"label":"Les couloirs bruissent de manœuvres"}],"news":"Le Président du Conseil défie le Parlement : « Déposez-la ! »"}]},{"id":"italie-q-assemblee-haute","theme":"assemblee","condition":{"gauge":"assemblee","op":">","value":60},"text":"Une majorité solide, c’est rare : certains vétérans du Parlement disent n’en avoir jamais vu hors des musées. N’allez-vous pas en abuser pour faire passer des textes à la hâte ?","answers":[{"tone":"franche","label":"Une majorité forte oblige à écouter davantage, pas moins. Je laisserai l’opposition amender, et même gagner de temps en temps.","effects":{"cohesion":4,"assemblee":-2,"popularite":2},"news":"Le Président du Conseil promet d’écouter l’opposition"},{"tone":"langue-de-bois","label":"Les textes seront examinés avec le sérieux qui s’impose, dans les délais prévus, avec les moyens appropriés et les formulaires requis.","effects":{"assemblee":2,"popularite":-2},"news":"Les textes seront examinés « avec les formulaires requis »"},{"tone":"offensive","label":"Les Italiens m’ont donné cette majorité pour agir. Si l’opposition veut des débats sans fin, elle a le théâtre de la rue Mazzini.","effects":{"economie":4,"popularite":2,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"L’opposition dénonce un passage en force"}],"news":"Le Président du Conseil accélère : « La majorité est faite pour agir »"}]},{"id":"italie-q-securite-haute","theme":"securite","condition":{"gauge":"securite","op":">","value":65},"text":"Les rues sont calmes et les statistiques sourient. Une organisation de défense des libertés vous demande si l’on a besoin de tant de patrouilles. Cherchez-vous un équilibre, ou un décor ?","answers":[{"tone":"franche","label":"La sécurité ne vaut que si elle respecte les libertés. Je réduirai les contrôles inutiles et je garderai les moyens utiles.","effects":{"cohesion":4,"securite":-3,"budget":2},"news":"Le gouvernement allège les contrôles inutiles"},{"tone":"langue-de-bois","label":"L’équilibre entre sécurité et liberté est subtil. Nous le cherchons chaque jour, et lui nous cherche à son tour.","effects":{"securite":2,"popularite":-2},"news":"Sécurité et liberté : l’exécutif cherche l’équilibre"},{"tone":"offensive","label":"Les rues sont calmes parce que nous veillons. Qu’on ne me demande pas de dormir parce que le résultat est bon.","effects":{"securite":4,"popularite":2,"cohesion":-3},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Un syndicat de policiers réclame des primes"}],"news":"Le Président du Conseil refuse de baisser la garde"}]},{"id":"italie-q-cr-tampon","theme":"crise","crisisId":"italie-tampon-manquant","text":"Un tampon manquant bloque des milliers de dossiers, et un fonctionnaire déclare qu’il faut « attendre le retour du timbre du mardi ». Le pays peut-il vraiment s’arrêter à cause d’un cachet d’encre ?","answers":[{"tone":"franche","label":"Nous avons créé une bureaucratie qui ne sait plus avancer sans ses cachets. J’en ferai une affaire personnelle jusqu’à ce que cela change.","effects":{"economie":4,"popularite":3,"budget":-3},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les dossiers se débloquent un à un"}],"news":"Le Président du Conseil prend personnellement le dossier du tampon"},{"tone":"langue-de-bois","label":"Une enquête interne a été ouverte afin de déterminer l’origine du tampon, sa trajectoire et ses perspectives de retour.","effects":{"popularite":-2,"economie":2},"news":"Une enquête cherche l’origine du tampon manquant"},{"tone":"offensive","label":"Faites imprimer des tampons en carton et distribuez-les ! Et que celui qui les refuse explique pourquoi à la télévision.","effects":{"popularite":4,"economie":3,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les fonctionnaires menacent de ne plus tamponner"}],"news":"Le gouvernement distribue des tampons en carton"}]},{"id":"italie-q-cr-viaduc","theme":"crise","crisisId":"italie-viaduc-fissure","text":"Un viaduc présente une fissure inquiétante, la route est coupée et le détour passe par une cathédrale. Qui répondra de l’état des ouvrages, et quand le trafic reviendra-t-il ?","answers":[{"tone":"franche","label":"Nous avons trop attendu pour entretenir nos routes. Je lance un plan de contrôle de tous les ouvrages, avec des résultats publics.","effects":{"securite":5,"budget":-4,"popularite":2},"delayed":[{"delay":3,"effects":{"securite":2},"label":"Les premiers rapports sont publiés"}],"news":"Le gouvernement lance un contrôle de tous les ouvrages"},{"tone":"langue-de-bois","label":"Les experts évaluent la situation. Leurs conclusions seront rendues dès que leurs conclusions auront été conclues.","effects":{"securite":2,"popularite":-3},"news":"Viaduc : l’exécutif attend les conclusions des experts"},{"tone":"offensive","label":"Les responsables seront identifiés et poursuivis, y compris dans les anciens gouvernements. On ne laisse pas un pont se fissurer en silence.","effects":{"popularite":4,"securite":2,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les anciens ministres répliquent aux accusations"}],"news":"Viaduc fissuré : le Président du Conseil cherche les coupables"}]},{"id":"italie-q-cr-coalition","theme":"crise","crisisId":"italie-coalition-vacille","text":"La coalition vacille, un partenaire menace de partir et un autre de revenir. Pouvez-vous dire aux Italiens, sans sourire, que ce gouvernement existera encore à Noël ?","answers":[{"tone":"franche","label":"Je ne peux rien promettre à l’avance, mais je peux promettre une chose : le travail continuera tant que la confiance sera là.","effects":{"assemblee":4,"popularite":2,"economie":-2},"delayed":[{"delay":2,"effects":{"assemblee":2},"label":"Les partenaires acceptent une trêve"}],"news":"Le Président du Conseil refuse de promettre l’avenir"},{"tone":"langue-de-bois","label":"Le gouvernement est solide, serein et serein dans sa solidité, comme dans les années précédentes que personne ne cite.","effects":{"assemblee":2,"popularite":-3},"news":"« Solide et serein » : le gouvernement jure sa stabilité"},{"tone":"offensive","label":"Que les partenaires qui veulent partir prennent la porte, mais qu’ils laissent la clé : je ne payerai pas un nouveau serrurier.","effects":{"popularite":4,"assemblee":-5,"international":-2},"delayed":[{"delay":3,"effects":{"assemblee":-3},"label":"Un partenaire claque la porte du conseil des ministres"}],"news":"Le Président du Conseil à ses alliés : « Laissez la clé »"}]},{"id":"italie-q-cr-greve","theme":"crise","crisisId":"italie-greve-du-vendredi","text":"Une nouvelle grève du vendredi paralyse les trains, et les voyageurs notent que le week-end commence désormais le jeudi soir. Qui gouverne les rails : vous, ou le calendrier ?","answers":[{"tone":"franche","label":"Les grévistes ont des raisons, et les voyageurs aussi. Je réunirai tout le monde jusqu’à ce qu’un accord tienne le week-end.","effects":{"cohesion":4,"budget":-3,"popularite":2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Un accord est trouvé pour trois mois"}],"news":"Grève du vendredi : le gouvernement réunit tout le monde"},{"tone":"langue-de-bois","label":"Le droit de grève est constitutionnel, comme le droit de circuler, et nous veillons à ce que chaque droit attende son tour.","effects":{"cohesion":2,"popularite":-3},"news":"Le gouvernement veut que « chaque droit attende son tour »"},{"tone":"offensive","label":"Il faut garantir un service minimum, un point c’est tout. Les voyageurs ne sont pas des otages, et je ne serai pas leur négociateur.","effects":{"popularite":5,"securite":2,"cohesion":-4,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":-3},"label":"Les syndicats appellent à une grève plus longue"}],"news":"Le Président du Conseil exige un service minimum"}]},{"id":"italie-q-cr-seisme","theme":"crise","crisisId":"italie-seisme-apennin","text":"Un séisme a secoué l’Apennin, des villages entiers sont fragilisés et des habitants dorment dans leur voiture. Quelle réponse donnez-vous à ceux qui attendent depuis des années les reconstructions promises ?","answers":[{"tone":"franche","label":"La première urgence est de loger et de soigner. Nous reconstruirons plus solide et plus vite, avec un calendrier public.","effects":{"cohesion":5,"budget":-5,"popularite":3},"delayed":[{"delay":3,"effects":{"cohesion":2,"securite":2},"label":"Les premiers villages sont remis aux normes"}],"news":"Séisme : un plan de relogement et de reconstruction"},{"tone":"langue-de-bois","label":"Nos pensées vont aux familles touchées. La reconstruction sera menée dans le respect des procédures, des délais et des tampons.","effects":{"cohesion":2,"popularite":-3},"news":"Séisme : la reconstruction se fera « dans le respect des tampons »"},{"tone":"offensive","label":"Plus jamais d’argent promis puis perdu en route ! J’exigerai des comptes aux bureaux et aux entreprises qui ont tardé.","effects":{"popularite":4,"cohesion":2,"economie":-3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Des entreprises du bâtiment se retirent des chantiers"}],"news":"Séisme : le Président du Conseil exige des comptes"}]},{"id":"italie-q-cr-spread","theme":"crise","crisisId":"italie-spread-dette","text":"Le spread s’affole, les marchés s’impatientent et un commentateur compare votre budget à un exercice d’équilibriste sans filet. Faut-il s’attendre à de nouveaux sacrifices pour calmer les prêteurs ?","answers":[{"tone":"franche","label":"Nous ferons des économies là où elles sont possibles, sans casser ce qui marche. Les marchés regardent, mais les Italiens passent avant.","effects":{"economie":3,"budget":4,"pouvoirAchat":-3},"delayed":[{"delay":3,"effects":{"international":2},"label":"Le spread se détend légèrement"}],"news":"Le gouvernement promet des économies ciblées"},{"tone":"langue-de-bois","label":"Les marchés sont ce qu’ils sont, et nous sommes ce que nous sommes. Une rencontre entre les deux est possible dans l’avenir.","effects":{"budget":2,"popularite":-3},"news":"Spread : « les marchés sont ce qu’ils sont »"},{"tone":"offensive","label":"Un pays n’a pas à trembler chaque fois qu’un trader éternue. Je ne gouvernerai pas à l’heure de la Bourse.","effects":{"popularite":5,"international":-3,"budget":-4},"delayed":[{"delay":2,"effects":{"economie":-3},"label":"Les taux de financement grimpent encore"}],"news":"Le Président du Conseil refuse de gouverner « à l’heure de la Bourse »"}]},{"id":"italie-q-cr-generique","theme":"crise","text":"Dans une crise, on voit les dirigeants au bout d’une heure, et leurs communiqués au bout de trois jours. Pourquoi ne pas avoir parlé plus vite, et surtout, plus clairement ?","answers":[{"tone":"franche","label":"J’aurais dû parler plus tôt et moins longuement. Désormais, un point de situation quotidien, même s’il ne dit que « rien de neuf ».","effects":{"popularite":4,"cohesion":2,"assemblee":-2},"news":"Le gouvernement promet un point quotidien en cas de crise"},{"tone":"langue-de-bois","label":"Le gouvernement a communiqué de manière appropriée, mesurée et conforme au protocole, qui prévoit un silence constructif.","effects":{"assemblee":2,"popularite":-3},"news":"Le protocole prévoit un « silence constructif »"},{"tone":"offensive","label":"La crise appartient à ceux qui la gèrent, pas à ceux qui la commentent. Mon silence valait mieux que vos éditoriaux.","effects":{"popularite":3,"securite":2,"international":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"La presse prépare sa réponse"}],"news":"Le Président du Conseil critique les éditorialistes"}]},{"id":"italie-q-cr-canicule","theme":"crise","text":"Les trottoirs fondent, les climatiseurs sont en rupture et les nonnes demandent la permission de sortir en pantoufles. Que fait le gouvernement face à une chaleur qui dure plus que ses coalitions ?","answers":[{"tone":"franche","label":"Nous ouvrons des salles fraîches, nous aidons les personnes âgées et nous préparons les villes à des étés plus durs.","effects":{"cohesion":4,"ecologie":3,"budget":-4},"delayed":[{"delay":3,"effects":{"ecologie":2},"label":"Des arbres sont plantés dans les centres-villes"}],"news":"Canicule : des salles fraîches ouvertes dans les villes"},{"tone":"langue-de-bois","label":"La chaleur est un phénomène saisonnier. Le gouvernement recommande de boire de l’eau et d’attendre septembre avec confiance.","effects":{"popularite":-3,"securite":2},"news":"Chaleur : le gouvernement recommande d’attendre septembre"},{"tone":"offensive","label":"Les Italiens ont connu pire sous les Romains, et ils avaient des toges. Je ne dirai pas non à une bonne sieste nationale.","effects":{"popularite":5,"securite":-2,"economie":-3},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les usines tournent au ralenti"}],"news":"Le Président du Conseil approuve la sieste nationale"}]},{"id":"italie-q-sc-conflit","theme":"scandale","text":"On a découvert qu’un de vos ministres a confié l’organisation d’un congrès sur la transparence à la société de son beau-frère. Faut-il y voir une conception très familiale de la transparence ?","answers":[{"tone":"franche","label":"Cette décision était une erreur, et je le dis sans détour. Le contrat est annulé et une règle interdira ce genre de contrat.","effects":{"popularite":4,"assemblee":-3,"cohesion":2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Le ministre est prié de se faire discret"}],"news":"Conflit d’intérêts : le contrat du beau-frère est annulé"},{"tone":"langue-de-bois","label":"Le ministre a respecté toutes les procédures, dont certaines ont été rédigées par son beau-frère. Il n’y a donc rien à signaler.","effects":{"assemblee":2,"popularite":-4},"news":"Le gouvernement : « Aucune irrégularité dans la famille »"},{"tone":"offensive","label":"Qu’on cesse de mêler la famille à la politique : c’est le dernier endroit où l’on trouve encore de la loyauté.","effects":{"assemblee":3,"popularite":-4,"cohesion":-3,"international":-2},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Un sondage condamne l’explication familiale"}],"news":"Le Président du Conseil défend « la loyauté familiale »"}]},{"id":"italie-q-sc-fuite","theme":"scandale","text":"Le contenu d’un conseil des ministres a fuité dans un journal avant la fin de la réunion, avec la liste des desserts. Soupçonnez-vous vos alliés, vos ministres, ou la machine à café ?","answers":[{"tone":"franche","label":"Quelqu’un parle trop, et je le saurai. Mais je ne veux pas gouverner dans la peur : nous resserrerons la confiance plutôt que les serrures.","effects":{"assemblee":4,"popularite":2,"cohesion":-2},"news":"Fuite au conseil : le Président du Conseil mise sur la confiance"},{"tone":"langue-de-bois","label":"Il est vrai que certains détails ont été divulgués. L’enquête s’intéressera à la fuite, au robinet, et à la plomberie générale.","effects":{"assemblee":2,"popularite":-3},"news":"Fuite : l’enquête s’intéresse à « la plomberie générale »"},{"tone":"offensive","label":"Désormais, les ministres laisseront leur téléphone à l’entrée. Et celui qui a révélé le menu est prié de révéler aussi la recette.","effects":{"popularite":4,"assemblee":-4,"cohesion":-2},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"Un ministre se plaint de n’avoir plus de réseau"}],"news":"Fuite : les ministres devront laisser leur téléphone à l’entrée"}]},{"id":"italie-q-sc-yacht","theme":"scandale","text":"Un conseiller a été photographié à bord d’un yacht prêté par un entrepreneur du bâtiment qui cherche un marché public. Il affirme avoir pris l’air pour réfléchir à la sobriété. Vous le croyez ?","answers":[{"tone":"franche","label":"Je ne le crois pas et je le lui ai dit. Il quitte ses fonctions, et le marché sera rouvert avec un nouvel appel d’offres.","effects":{"popularite":5,"assemblee":-2,"economie":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les Italiens saluent la fermeté"}],"news":"Yacht : le conseiller quitte ses fonctions, le marché rouvert"},{"tone":"langue-de-bois","label":"Le conseiller a été invité à fournir des explications. Elles seront étudiées dans un climat serein, et sur un bateau si nécessaire.","effects":{"assemblee":2,"popularite":-4},"news":"Yacht : le conseiller sera entendu « dans un climat serein »"},{"tone":"offensive","label":"Une photo ne prouve rien : on peut monter sur un yacht, comme dans un train, sans avoir l’intention d’aller quelque part.","effects":{"assemblee":3,"popularite":-3,"cohesion":-3},"delayed":[{"delay":3,"effects":{"popularite":-3},"label":"De nouvelles photos du yacht circulent"}],"news":"Yacht : le gouvernement conteste la valeur de la photo"}]},{"id":"italie-q-cu-foot","theme":"popularite","text":"L’équipe nationale a encore perdu un match qu’elle gagnait à la quatre-vingt-neuvième minute. Un gouvernement peut-il se permettre de ne rien dire quand le pays entier est en deuil ?","answers":[{"tone":"franche","label":"Le pays a le droit de pleurer, puis de repartir. Je vais proposer que la fédération rende des comptes, comme tout le monde.","effects":{"popularite":4,"cohesion":2,"assemblee":-2},"news":"Défaite : le gouvernement demande des comptes à la fédération"},{"tone":"langue-de-bois","label":"Les joueurs ont donné le meilleur d’eux-mêmes. L’arbitre aussi, probablement, mais ce n’est pas à moi de le dire.","effects":{"popularite":2,"international":-2},"news":"Le gouvernement défend les joueurs, ménage l’arbitre"},{"tone":"offensive","label":"Je ne m’occupe pas du football. Mais si l’arbitre est étranger, je ferai passer un message très cordial et très menaçant.","effects":{"popularite":5,"international":-4,"cohesion":2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"La fédération européenne répond avec une amende"}],"news":"Défaite : le Président du Conseil bombe le torse contre l’arbitre"}]},{"id":"italie-q-cu-cuisine","theme":"cohesion","text":"Une querelle oppose le nord et le sud sur la bonne façon de préparer la carbonara, avec ou sans crème. Un chef du gouvernement a-t-il son mot à dire sur la cuisine nationale ?","answers":[{"tone":"franche","label":"La carbonara n’a pas de crème, et je défendrai cette position jusqu’au prochain vote. La tradition vaut mieux que la mode.","effects":{"popularite":4,"cohesion":2,"international":-3},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Les cuisiniers étrangers se sentent visés"}],"news":"Le Président du Conseil se prononce contre la crème"},{"tone":"langue-de-bois","label":"La cuisine italienne est un patrimoine, plusieurs patrimoines même, et chaque famille garde le sien dans un tiroir de la cuisine.","effects":{"cohesion":3,"popularite":-2},"news":"Le gouvernement veut protéger tous les patrimoines culinaires"},{"tone":"offensive","label":"Nous créerons un comité de la carbonara. Il siégera dans un restaurant, ne conclura rien, et chacun défendra sa recette.","effects":{"popularite":3,"budget":-3,"cohesion":2},"news":"Un comité de la carbonara va siéger dans un restaurant"}]},{"id":"italie-q-cu-regions","theme":"cohesion","text":"Le nord réclame plus d’autonomie, le sud plus de moyens, et les îles plus de ferries. Peut-on gouverner un pays où chaque région se croit le centre du monde, et à juste titre ?","answers":[{"tone":"franche","label":"Chaque région a une vraie spécificité. Je négocierai des compétences accrues, mais avec un fonds de solidarité qui profite à tous.","effects":{"cohesion":5,"assemblee":-3,"budget":-2},"delayed":[{"delay":3,"effects":{"assemblee":2},"label":"La Ligue des Provinces accepte de discuter"}],"news":"Autonomie des régions : un fonds de solidarité en contrepartie"},{"tone":"langue-de-bois","label":"Chaque région compte et sera consultée, puis écoutée, puis consultée de nouveau, afin de garantir l’équité de la consultation.","effects":{"cohesion":2,"popularite":-2},"news":"Les régions seront « consultées, puis consultées de nouveau »"},{"tone":"offensive","label":"Le pays est un, la botte est une, et personne ne coupera une chaussure en morceaux pour contenter une province.","effects":{"popularite":4,"assemblee":3,"cohesion":-5},"delayed":[{"delay":2,"effects":{"cohesion":-2},"label":"La Ligue des Provinces dénonce un mépris centralisateur"}],"news":"Le Président du Conseil refuse de « couper la botte »"}]},{"id":"italie-q-cu-temps","theme":"popularite","text":"Le président de la République arrive en retard à une cérémonie, vous aussi, et la fanfare avait déjà joué trois fois l’hymne. Les Italiens ont-ils un rapport particulier au temps, ou aux horaires affichés ?","answers":[{"tone":"franche","label":"Nous avons du retard, c’est vrai. J’accepte la critique, mais les horaires sont une invention du Nord.","effects":{"popularite":3,"cohesion":-2},"news":"Le Président du Conseil avoue son retard, accuse les horaires"},{"tone":"langue-de-bois","label":"Le temps est une notion relative, comme l’a dit un célèbre physicien, qui n’a sûrement jamais pris le train régional.","effects":{"popularite":2,"economie":-2},"news":"Le temps est « relatif » pour le gouvernement"},{"tone":"offensive","label":"Le retard est un art. Les cérémonies qui commencent à l’heure sont suspectes : cela signifie que personne ne s’y amuse.","effects":{"popularite":5,"economie":-3,"international":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les investisseurs étrangers regardent leur montre"}],"news":"Le Président du Conseil défend l’art du retard"}]},{"id":"italie-q-cu-tourisme","theme":"international","text":"Des villes d’art doivent limiter l’accès aux touristes, au point qu’un guide a ouvert une file d’attente pour les files d’attente. Faut-il protéger le patrimoine ou le porte-monnaie ?","answers":[{"tone":"franche","label":"Nous limiterons les flux là où la beauté s’abîme. Nous répartirons le tourisme dans les villages qui n’en voient jamais.","effects":{"ecologie":4,"cohesion":2,"economie":-3},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Des villages découvrent les visiteurs"}],"news":"Tourisme : mieux répartir les visiteurs sur tout le territoire"},{"tone":"langue-de-bois","label":"Le patrimoine est notre fierté, le tourisme notre réalité. Entre les deux, nous cherchons le juste milieu et un parking.","effects":{"economie":2,"popularite":-2},"news":"Patrimoine ou tourisme : l’exécutif cherche « un parking »"},{"tone":"offensive","label":"Les visiteurs sont les bienvenus et paieront leur place, comme dans toute bonne salle de spectacle. La beauté a un prix.","effects":{"economie":4,"budget":3,"international":-3,"popularite":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Les offices de tourisme étrangers protestent"}],"news":"Une taxe d’entrée pour les villes d’art"}]},{"id":"italie-q-cu-pate","theme":"pouvoirAchat","text":"Un spécialiste affirme que la pizza congelée menace l’identité nationale, et que le rôle du gouvernement est de dire à qui sert le four. Où placez-vous la limite entre l’État et la pâte ?","answers":[{"tone":"franche","label":"Je défendrai les artisans, pas par la force mais par un label clair. Chacun mange ce qu’il veut, en sachant ce qu’il mange.","effects":{"economie":3,"pouvoirAchat":-2,"cohesion":2},"news":"Un label clair pour distinguer pizza artisanale et surgelée"},{"tone":"langue-de-bois","label":"La pizza, qu’elle soit congelée ou fraîche, est un sujet sensible, et nous la traitons avec la délicatesse qu’elle exige.","effects":{"popularite":-2,"cohesion":2},"news":"Le gouvernement traite la pizza « avec délicatesse »"},{"tone":"offensive","label":"Je n’ai jamais mangé de pizza congelée. Ou alors une seule fois, en 1996, et j’en garde un souvenir traumatique.","effects":{"popularite":4,"pouvoirAchat":-3,"cohesion":2},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"Un fabricant de pizzas surgelées exige des excuses"}],"news":"Le Président du Conseil confesse un traumatisme de pizza"}]}]}'),u={pays:e,version:1,textes:s,institutions:n,election:t,lois:i,crises:a,missions:r,presse:o};export{a as crises,u as default,t as election,n as institutions,i as lois,r as missions,e as pays,o as presse,s as textes,l as version};
